CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,phone TEXT,role TEXT NOT NULL CHECK(role IN ('admin','customer','wholesale','seller','influencer')),password_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS applications (id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('seller','influencer','wholesale')),name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,city TEXT,social TEXT,notes TEXT,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category TEXT NOT NULL,price_cents INTEGER NOT NULL,wholesale_cents INTEGER,stock INTEGER NOT NULL DEFAULT 0,image_key TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coupons (code TEXT PRIMARY KEY,partner_id TEXT NOT NULL REFERENCES users(id),discount_bps INTEGER NOT NULL DEFAULT 0,commission_bps INTEGER NOT NULL DEFAULT 2000,active INTEGER NOT NULL DEFAULT 1,uses INTEGER NOT NULL DEFAULT 0,max_uses INTEGER,expires_at TEXT);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),customer_name TEXT NOT NULL,customer_email TEXT NOT NULL,customer_phone TEXT,shipping_address TEXT NOT NULL,subtotal_cents INTEGER NOT NULL,discount_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending_payment',coupon_code TEXT,partner_id TEXT,commission_bps INTEGER NOT NULL DEFAULT 0,commission_cents INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,quantity INTEGER NOT NULL,unit_price_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS commissions (id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),partner_id TEXT NOT NULL REFERENCES users(id),amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS videos (id TEXT PRIMARY KEY,title TEXT NOT NULL,object_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,entity_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_orders_partner ON orders(partner_id,created_at);
CREATE INDEX IF NOT EXISTS idx_applications_status ON applications(status);
CREATE INDEX IF NOT EXISTS idx_commissions_partner ON commissions(partner_id,status);
